data = json.loads(DATA.read_text(encoding='utf8'))
names = [d['name'] for d in data['domains']]
if D_ABBR not in names:
    data['domains'].append({'name': D_ABBR, 'study': '교재·약물 파트의 영문 약어, DSM-5 진단명 영문 표기(첨부 진단명 목록), 평가도구 약어'})
existing = {q['q'] for q in data['questions']}
added = 0
for dom, prefix, rows in [(D_ABBR, 'abbr', ABBR), (D_DSM, 'dsm2', DSM), (D_THEORY, 'thy2', THEORY), (D_LAW, 'law', LAW)]:
    n0 = sum(1 for q in data['questions'] if q['id'].startswith(prefix + '-'))
    for i, (lv, q, a, w, e, src) in enumerate(rows):
        if q in existing: continue
        data['questions'].append({'id': f'{prefix}-{n0 + i + 1:03d}', 'd': dom, 'lv': lv, 'q': q, 'a': a, 'w': w, 'e': e,
                                  'src': {**SRC[src], 'checked': '2026-11-13'}, 'st': 'draft'})
        existing.add(q); added += 1
data['version'] = '2026-11-13b'
DATA.write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding='utf8')
print('추가', added, '문항 / 전체', len(data['questions']))
